// 12 - Count Leads and Conversions by Source
// Input: Zoho's reply from step 11, the newest 200 leads, converted ones included.
// Output: one row per Lead Source for the Lead Dashboard tab, last 30 days.
const leads = $input.all().flatMap(item => item.json.data || []);
const since = DateTime.now().minus({ days: 30 });
const bySource = {};

for (const lead of leads) {
  if (DateTime.fromISO(lead.Created_Time) < since) continue;
  const source = lead.Lead_Source || 'No source';
  bySource[source] = bySource[source] || { leads: 0, converted: 0 };
  bySource[source].leads += 1;
  if (lead.$converted) bySource[source].converted += 1;
}

const updatedAt = DateTime.now().toFormat('yyyy-LL-dd');
return Object.entries(bySource).map(([source, count]) => ({
  json: {
    source,
    leads_last_30_days: count.leads,
    converted: count.converted,
    conversion_rate: Math.round((count.converted / count.leads) * 100) + '%',
    updated_at: updatedAt,
  },
}));
